  // ── Public API ───────────────────────────────────────────────────────────────

  /// Returns available [InsurancePlan]s for the given [categoryCode] and
  /// [countryCode], priced for all [travellerAges] over [durationDays].
  ///
  /// For annual plans the duration is treated as 365.
  static List<InsurancePlan> lookupPlans({
    required String categoryCode,
    required String countryCode,
    required List<int> travellerAges,
    required int durationDays,
  }) {
    final int age = travellerAges.isNotEmpty ? travellerAges[0] : 25;
    final int days = durationDays < 1 ? 1 : durationDays;
    final result = <InsurancePlan>[];

    for (final planRow in _plans) {
      if (planRow[2] != categoryCode || planRow[3] != countryCode) continue;

      final planCode = planRow[0];
      final entries = _chart[planCode];
      if (entries == null || entries.isEmpty) continue;

      // Pick the single cheapest entry where ageLimit >= age AND dayLimit >= days.
      // This gives one card per base plan rather than one card per age/day cell.
      final candidates = entries
          .where((e) => e[0].toInt() >= age && e[1].toInt() >= days)
          .toList();

      if (candidates.isEmpty) continue;

      // Cheapest qualifying premium
      candidates.sort((a, b) => a[2].compareTo(b[2]));
      final entry = candidates.first;
      final premium = entry[2].toDouble();

      result.add(InsurancePlan(
        id: '${planCode}_${entry[0]}_${entry[1]}',
        name: planRow[1],
        premium: premium,
        baseCharge: _baseCharge(premium),
        serviceTax: _serviceTax(premium),
        features: _featuresFor(planRow[1]),
      ));
    }

    return result;
  }

  static double _baseCharge(double premium) =>
      double.parse((premium / 1.18).toStringAsFixed(2));

  static double _serviceTax(double premium) =>
      double.parse((premium - premium / 1.18).toStringAsFixed(2));

  static List<String> _featuresFor(String name) {
    final n = name.toLowerCase();
    if (n.contains('domestic')) {
      return ['Emergency Medical Assistance', 'Domestic Roadside Assistance', 'Personal Accident'];
    }
    if (n.contains('annual')) {
      return ['Emergency Medical Assistance', 'Trip Cancellation', 'Annual Multi-trip'];
    }
    return ['Emergency Medical Assistance', 'Trip Cancellation', 'Loss of Baggage'];
  }
}
